window.HOEREN_TESTS[77] = {"id":"in-der-tanzschule","name":"In der Tanzschule","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Tanzschüler: Unser Anfängerkurs für Standardtanz beginnt nicht am Montag und nicht am Freitag, sondern erst am Mittwoch. Der Grund: zu wenige Anmeldungen für Montag. Mittwochs um 19 Uhr, zehn Wochen lang. Bringen Sie bitte Schuhe mit glatter Sohle mit. Wir freuen uns auf Sie und viele schöne Tänze!","gender":"f","q":"Wann beginnt der Kurs?","opts":["Am Mittwoch.","Am Montag.","Am Freitag."],"correct":0},{"transcript":"Hallo Tom, hier ist Markus. Also, ich heirate im Sommer und kann überhaupt nicht tanzen! Meine Verlobte besteht auf einem schönen Hochzeitstanz, nicht auf einem Wettbewerb und nicht nur auf einer Party. Gehst du mit mir zu einem Tanzkurs? Allein traue ich mich nicht. Es gibt extra Kurse für Hochzeitspaare. Bitte sag ja!","gender":"m","q":"Warum möchte Markus tanzen lernen?","opts":["Für einen Wettbewerb.","Für seinen Hochzeitstanz.","Für eine Party."],"correct":1},{"transcript":"Achtung Schüler: Der Tanzlehrer Herr Berg ist diese Woche krank, er ist nicht im Urlaub und hat nicht gekündigt. Seine Kurse fallen aus. Statt am Dienstag findet die Salsa-Stunde erst nächste Woche wieder statt. Wer möchte, kann in der Zeit den Kurs von Frau Klein besuchen — gleiche Uhrzeit, anderer Raum. Gute Besserung an Herrn Berg!","gender":"m","q":"Was ist mit Herrn Berg?","opts":["Er ist im Urlaub.","Er hat gekündigt.","Er ist krank."],"correct":2},{"transcript":"Hi Lisa, hier ist Anna. Ich tanze jetzt jeden Donnerstag Salsa und es macht so viel Spaß, nicht Walzer und nicht Tango! Aber mir fehlt ein Partner, die meisten kommen zu zweit. Magst du mitkommen? Du musst nichts können, der Lehrer erklärt alles. Es ist auch gut gegen Stress. Sag bitte zu, bis bald!","gender":"f","q":"Welchen Tanz tanzt Anna?","opts":["Walzer.","Salsa.","Tango."],"correct":1},{"transcript":"Liebe Gäste: Am Samstagabend findet unser großer Tanzball statt. Live-Musik, ein Buffet und natürlich viel Tanzfläche. Karten kosten im Vorverkauf 20 Euro, an der Abendkasse 25, nicht 15 Euro. Schicke Kleidung ist erwünscht. Auch wer keinen Kurs besucht, ist herzlich willkommen. Tanzen Sie mit uns! Kommen Sie, es wird ein schöner Abend!","gender":"f","q":"Was kosten die Karten im Vorverkauf?","opts":["20 Euro.","25 Euro.","15 Euro."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Welchen Tanz üben sie an welchem Tag? Wählen Sie für jeden Tag einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Der Wochenplan hängt an der Tür. Hast du ihn schon gelesen?"},{"speaker":"Lisa","gender":"f","text":"Ich habe ihn noch nicht gelesen. Ich habe nur die Schuhe dabei und wir können nicht alles an einem Tag üben."},{"speaker":"Lukas","gender":"m","text":"Ich übe am Montag Salsa. Die Musik ist schnell und ein Freund tanzt mit."},{"speaker":"Lisa","gender":"f","text":"Steht Ballett diese Woche auf dem Plan?"},{"speaker":"Lukas","gender":"m","text":"Für Ballett ist kein Platz mehr. Der Kurs ist schon voll."},{"speaker":"Lisa","gender":"f","text":"Dann bleibe ich am Dienstag beim Walzer. Der große Raum ist frei und mein Kleid passt dazu."},{"speaker":"Lukas","gender":"m","text":"Tom kommt am Mittwoch und er übt Hip-Hop mit seinen Freunden."},{"speaker":"Lisa","gender":"f","text":"Das ist laut. Reicht der kleine Raum hinten?"},{"speaker":"Lukas","gender":"m","text":"Sie tanzen im Raum nebenan. Wollen wir Breakdance üben?"},{"speaker":"Lisa","gender":"f","text":"Breakdance wollen wir auch nicht üben."},{"speaker":"Lukas","gender":"m","text":"Sara kommt am Donnerstag und sie übt Tango."},{"speaker":"Lisa","gender":"f","text":"Tango geht langsam und die zwei bleiben eng zusammen."},{"speaker":"Lukas","gender":"m","text":"Am Freitag übt Tim Discofox."},{"speaker":"Lisa","gender":"f","text":"Das lernt er schnell und auf jeder Feier hat er Spaß."},{"speaker":"Lukas","gender":"m","text":"Dann hänge ich den Plan an die Tür."},{"speaker":"Lisa","gender":"f","text":"Ich lege die Schuhe schon heute Abend bereit."}],"options":[{"letter":"a","text":"Hip-Hop"},{"letter":"b","text":"Cha-Cha-Cha"},{"letter":"c","text":"Salsa"},{"letter":"d","text":"Foxtrott"},{"letter":"e","text":"Discofox"},{"letter":"f","text":"Ballett"},{"letter":"g","text":"Walzer"},{"letter":"h","text":"Breakdance"},{"letter":"i","text":"Tango"}],"items":[{"person":"Montag","correct":"c"},{"person":"Dienstag","correct":"g"},{"person":"Mittwoch","correct":"a"},{"person":"Donnerstag","correct":"i"},{"person":"Freitag","correct":"e"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, was kostet der Kurs? 120 Euro oder 240 Euro für uns beide?"},{"speaker":"Lehrer","gender":"m","text":"Zehn Stunden für 120 Euro pro Person, nicht 240 Euro."},{"speaker":"Kundin","gender":"f","text":"Und für ein Paar, 240 Euro?"},{"speaker":"Lehrer","gender":"m","text":"Als Paar 200 Euro, also günstiger. Nicht 120 für beide und nicht 240."},{"speaker":"Kundin","gender":"f","text":"Dann nehmen wir den Paar-Preis, 200 Euro. Danke schön. Bis Mittwoch!"}],"q":"Was kostet der Kurs für ein Paar?","opts":["120 Euro.","240 Euro.","200 Euro."],"correct":2},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag, brauche ich besondere Schuhe? Sportschuhe oder Stiefel?"},{"speaker":"Lehrerin","gender":"f","text":"Am Anfang reichen Schuhe mit glatter Sohle. Keine Sportschuhe und keine Stiefel."},{"speaker":"Mann","gender":"m","text":"Also keine Sportschuhe und keine Stiefel?"},{"speaker":"Lehrerin","gender":"f","text":"Nein, Sportschuhe bleiben am Boden kleben. Glatte Sohle ist besser."},{"speaker":"Mann","gender":"m","text":"Gut, dann kaufe ich Schuhe mit glatter Sohle. Danke."}],"q":"Welche Schuhe soll der Mann tragen?","opts":["Sportschuhe.","Schuhe mit glatter Sohle.","Stiefel."],"correct":1},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag, ich habe noch nie getanzt. Ist der Kurs für Profis oder für Kinder?"},{"speaker":"Lehrer","gender":"m","text":"Kein Problem, der Kurs ist für Anfänger, nicht für Profis und nicht für Kinder."},{"speaker":"Frau","gender":"f","text":"Und wenn ich es nicht schaffe, als Anfängerin?"},{"speaker":"Lehrer","gender":"m","text":"Jeder lernt es, das verspreche ich. Der Anfängerkurs ist genau richtig für Sie."},{"speaker":"Frau","gender":"f","text":"Dann mache ich den Anfängerkurs. Danke, ich freue mich."}],"q":"Für wen ist der Kurs?","opts":["Für Anfänger.","Für Profis.","Für Kinder."],"correct":0},{"lines":[{"speaker":"Schüler","gender":"m","text":"Guten Tag, wann ist die nächste Anfänger-Stunde? Freitag oder Samstag?"},{"speaker":"Lehrerin","gender":"f","text":"Donnerstag um 19 Uhr, nicht Freitag und nicht Samstag."},{"speaker":"Schüler","gender":"m","text":"Kann ich auch freitags kommen, zur Anfänger-Stunde?"},{"speaker":"Lehrerin","gender":"f","text":"Freitags ist nur der Fortgeschrittenen-Kurs. Anfänger ist Donnerstag."},{"speaker":"Schüler","gender":"m","text":"Verstehe, dann komme ich Donnerstag um 19 Uhr. Danke, bis dann!"}],"q":"Wann ist die nächste Anfänger-Stunde?","opts":["Freitag.","Donnerstag.","Samstag."],"correct":1},{"lines":[{"speaker":"Vater","gender":"m","text":"Guten Tag, meine Tochter möchte Ballett lernen, nicht Salsa und nicht Hip-Hop."},{"speaker":"Lehrerin","gender":"f","text":"Wie alt ist sie? Salsa und Hip-Hop sind eher für Ältere."},{"speaker":"Vater","gender":"m","text":"Sechs Jahre. Ballett ist gut, oder?"},{"speaker":"Lehrerin","gender":"f","text":"Perfekt, samstags gibt es einen Kinderkurs für Ballett. Salsa und Hip-Hop sind später."},{"speaker":"Vater","gender":"m","text":"Dann nehme ich den Ballett-Kurs am Samstag. Danke schön."}],"q":"Was möchte die Tochter lernen?","opts":["Ballett.","Salsa.","Hip-Hop."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Tanaka, einer Tanzlehrerin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Tanaka, Sie unterrichten seit 20 Jahren Tanz. Wer kommt zu Ihnen?"},{"speaker":"Tanaka","gender":"f","text":"Ganz unterschiedliche Leute. Junge Paare vor der Hochzeit, das ist ein Klassiker. Aber auch ältere Menschen, die nach der Rente etwas Neues lernen wollen. Und immer mehr Singles, die nette Leute kennenlernen möchten. Tanzen verbindet, das ist das Schöne daran."},{"speaker":"Reporter","gender":"m","text":"Haben viele Angst, sich zu blamieren?"},{"speaker":"Tanaka","gender":"f","text":"Oh ja, fast alle am Anfang. Besonders die Männer denken, sie haben zwei linke Füße. Aber das ist Unsinn. Tanzen kann jeder lernen, man braucht nur etwas Geduld. Nach ein paar Stunden lacht keiner mehr über sich selbst, alle haben einfach Spaß."},{"speaker":"Reporter","gender":"m","text":"Ist Tanzen auch gesund?"},{"speaker":"Tanaka","gender":"f","text":"Sehr sogar! Es ist Sport und Spaß zugleich. Man bewegt sich, trainiert das Gedächtnis mit den Schritten und das Herz wird fit. Studien zeigen sogar, dass Tanzen gut gegen das Vergessen im Alter hilft. Ich kenne kaum etwas Gesünderes, das so viel Freude macht."},{"speaker":"Reporter","gender":"m","text":"Was ist der häufigste Fehler von Anfängern?"},{"speaker":"Tanaka","gender":"f","text":"Sie schauen ständig auf ihre Füße. Dabei muss man fühlen, nicht sehen. Und sie wollen zu schnell zu viel. Ich sage immer: Lernt erst einen Schritt richtig, dann den nächsten. Wer alles auf einmal will, verliert den Spaß. Geduld ist beim Tanzen das Wichtigste."},{"speaker":"Reporter","gender":"m","text":"Was möchten Sie den Menschen sagen?"},{"speaker":"Tanaka","gender":"f","text":"Trauen Sie sich! Es ist nie zu spät, das Tanzen zu lernen. Egal ob mit zwanzig oder mit siebzig. Tanzen macht glücklich, hält gesund und bringt Menschen zusammen. Kommen Sie einfach in eine Probestunde. Ich verspreche, Sie werden lächelnd nach Hause gehen."}],"items":[{"q":"Zu Frau Tanaka kommen auch ältere Menschen nach der Rente.","correct":"ja"},{"q":"Sie findet, dass nicht jeder tanzen lernen kann.","correct":"nein"},{"q":"Tanzen ist laut ihr gut für Herz und Gedächtnis.","correct":"ja"},{"q":"Anfänger schauen oft zu viel auf ihre Füße.","correct":"ja"},{"q":"Sie meint, zum Tanzenlernen sei man mit siebzig zu alt.","correct":"nein"}]}]};
